# The scale that avoids underflow depends on the gradient distribution,
# which moves during training. So search for it online.
S, clean, growth_interval = 2**15, 0, 2000
for step in ...:
    grads = backward(loss * S)
    if any(isinf(g) or isnan(g) for g in grads):
        S /= 2; clean = 0        # back off, and SKIP the optimizer step
    else:
        step_optimizer(grads / S)
        clean += 1
        if clean == growth_interval:
            S *= 2; clean = 0    # probe upward again
# Steady state: <= 1 skipped step per 2000 = 0.05% of steps.
